 "content": "from collections import deque


def transform(grid):
    """Replace large solid monochrome rectangular regions with color 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            min_r = min(y for y, _ in cells)
            max_r = max(y for y, _ in cells)
            min_c = min(x for _, x in cells)
            max_c = max(x for _, x in cells)
            height, width = max_r - min_r + 1, max_c - min_c + 1
            if height >= 5 and width >= 5 and len(cells) >= 30 and len(cells) == height * width:
                for y, x in cells:
                    out[y][x] = 4
    return out
