 "new_string": "def transform(grid):
    """Only recolor the dominant planted monochrome rectangles (4 to 4)."""
    from collections import deque

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny,nx))
            minr=min(y for y,x in cells); maxr=max(y for y,x in cells)
            minc=min(x for y,x in cells); maxc=max(x for y,x in cells)
            hh,ww=maxr-minr+1,maxc-minc+1
            if len(cells)==hh*ww and hh>=5 and ww>=5:
                components.append((len(cells),color,cells))
    if components:
        # Planted solid fills are among the largest rectangular components;
        # discard broad uniform background-like component if present.
        sizes=sorted((x[0] for x in components), reverse=True)
        threshold=max(25, sizes[0]//4 if len(sizes)>1 else sizes[0])
        for size,color,cells in components:
            if size>=threshold:
                for y,x in cells:
                    out[y][x]=4
    return out
