    """Recolor the interior of any 5x5-or-larger monochrome patch to 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = grid[r][c]
            if color == 4:
                continue
            # Axially bounded solid runs indicate a planted patch, not field texture.
            for top in range(max(1, r - 5), min(r, h - 6) + 1):
                for left in range(max(1, c - 5), min(c, w - 6) + 1):
                    for hh in range(5, min(10, h - 1 - top) + 1):
                        if r >= top + hh:
                            continue
                        for ww in range(5, min(10, w - 1 - left) + 1):
                            if c >= left + ww:
